  void Log(string text){C<TextBox>("LogBox").AppendText(DateTime.Now.ToString("HH:mm")+"  "+text+Environment.NewLine);C<TextBlock>("FooterStatus").Text=text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).LastOrDefault()??"";}
  void Fail(Exception e){Log(e.Message);MessageBox.Show(Window,e.Message,L("Не удалось выполнить","Could not complete","Не вдалося виконати"),MessageBoxButton.OK,MessageBoxImage.Information);}
  void Bind(string name,Action action){C<Button>(name).Click+=(s,e)=>{try{action();}catch(Exception ex){Fail(ex);}};}
  void BindAsync(string name,Func<Task> action){C<Button>(name).Click+=async(s,e)=>{if(busy)return;busy=true;try{await action();}catch(Exception ex){Fail(ex);}finally{busy=false;}};}
  public ModernLauncher(){
   using(var input=File.OpenRead(Path.Combine(root,"launcher","Modern.xaml")))Window=(Window)XamlReader.Load(input);
   string icon=Path.Combine(root,"launcher","assets","soundspace.ico");if(File.Exists(icon)){var bitmap=BitmapFrame.Create(new Uri(icon));Window.Icon=bitmap;C<Image>("BrandIcon").Source=BitmapFrame.Create(new Uri(Path.Combine(root,"launcher","assets","soundspace.png")));}
   C<FrameworkElement>("DragBar").MouseLeftButtonDown+=(s,e)=>{if(e.ClickCount==2)Window.WindowState=Window.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;else if(e.LeftButton==MouseButtonState.Pressed)Window.DragMove();};
   Bind("CloseButton",()=>Window.Close());Bind("MinimizeButton",()=>Window.WindowState=WindowState.Minimized);
   Bind("DiscoverTab",()=>View("Discover"));Bind("LibraryTab",()=>View("Library"));Bind("SettingsTab",()=>View("Settings"));BindAsync("PublicationsTab",async()=>{View("Publications");await MyPublications();});BindAsync("RefreshPublicationsButton",MyPublications);
   Bind("LangRu",()=>SetLanguage("RU"));Bind("LangEn",()=>SetLanguage("EN"));Bind("LangUk",()=>SetLanguage("UK"));
   Bind("ImportButton",Import);Bind("ExportButton",Export);BindAsync("ApplyButton",()=>RunPatch("Apply"));BindAsync("RestoreButton",()=>RunPatch("Restore"));BindAsync("StatusButton",()=>RunPatch("Status"));
   BindAsync("SearchButton",()=>Refresh(false));BindAsync("LoadMoreButton",()=>Refresh(true));BindAsync("SortButton",async()=>{sort=sort=="new"?"popular":"new";Localize();await Refresh(false);});
   C<TextBox>("SearchBox").KeyDown+=async(s,e)=>{if(e.Key==Key.Enter&&!busy){try{await Refresh(false);}catch(Exception ex){Fail(ex);}}};
   C<Button>("AccountButton").Click+=async(s,e)=>{try{await Account();}catch(Exception ex){Fail(ex);}};C<Button>("PublishButton").Click+=async(s,e)=>{try{await Publish();}catch(Exception ex){Fail(ex);}};
   BindAsync("SaveServerButton",async()=>{string value=C<TextBox>("ServerBox").Text.Trim().TrimEnd('/');Uri uri;if(!Uri.TryCreate(value,UriKind.Absolute,out uri)||(uri.Scheme!="https"&&!(uri.Scheme=="http"&&uri.IsLoopback)))throw new InvalidOperationException("Use an HTTPS server URL.");if(value!=server){token="";username="";}server=value;Save();Localize();View("Discover");await Refresh(false);});
   player.MediaFailed+=(s,e)=>Fail(e.ErrorException);
   Window.Closing+=(s,e)=>{if(busy){e.Cancel=true;return;}player.Close();Save();};
   foreach(var key in Packs.Keys)sounds[key]=null;
   foreach(var file in new[]{"teamspeak-female.dspack","teamspeak-male.dspack","classic-clicks.dspack"}){string path=Path.Combine(root,"presets",file);if(File.Exists(path))presets.Add(Packs.Import(path));}
   if(presets.Count>0)Use(presets[0],false);Load();if(server==""&&File.Exists(Path.Combine(root,"launcher","service.json"))){var service=Packs.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(root,"launcher","service.json")));server=Packs.Text(service,"url").TrimEnd('/');C<TextBox>("ServerBox").Text=server;}loading=false;Localize();DrawPresets();DrawSounds();DrawCategories();View("Discover");
   C<TextBox>("PackNameBox").TextChanged+=(s,e)=>Save();
   Window.ContentRendered+=async(s,e)=>{C<Button>("DiscoverTab").Focus();C<ScrollViewer>("ContentScroll").ScrollToTop();if(server!="")try{await Refresh(false);}catch(Exception ex){C<TextBlock>("CommunityStatus").Text=ex.Message;}else Offline();};
  }
  void View(string name){foreach(string key in new[]{"Discover","Library","Publications","Settings"}){C<StackPanel>(key+"View").Visibility=name==key?Visibility.Visible:Visibility.Collapsed;string tab=key=="Discover"?"DiscoverTab":key=="Library"?"LibraryTab":key=="Publications"?"PublicationsTab":"SettingsTab";C<Button>(tab).Background=name==key?Orange:Brushes.Transparent;C<Button>(tab).Foreground=name==key?Brushes.Black:Brushes.White;}if(name=="Library")DrawSounds();}
  void SetLanguage(string value){language=value;Localize();DrawPresets();DrawSounds();DrawCategories();if(server=="")Offline();Save();}
