   C<Button>("DiscoverTab").Content=L("Обзор","Discover","Огляд");C<Button>("LibraryTab").Content=L("Мои звуки","My sounds","Мої звуки");C<Button>("SettingsTab").Content=L("Настройки","Settings","Налаштування");C<TextBlock>("StudioTitle").Text=L("От SoundSpace","From SoundSpace","Від SoundSpace");C<TextBlock>("CommunityTitle").Text=L("От сообщества","From the community","Від спільноти");C<TextBlock>("CommunityDescription").Text=L("Звуки, которыми делятся другие пользователи. Слушай, выбирай и добавляй в свою коллекцию.","Sounds shared by other people. Preview, explore, and add them to your collection.","Звуки, якими діляться інші користувачі. Слухай, вибирай і додавай до колекції.");
   C<Button>("PublishButton").Content=L("↑  Поделиться паком","↑  Share a pack","↑  Поділитися паком");C<Button>("SearchButton").Content=L("Найти","Search","Знайти");C<Button>("SortButton").Content=sort=="new"?L("Новые ↓","Newest ↓","Нові ↓"):L("Популярные ↓","Popular ↓","Популярні ↓");C<Button>("PublicationsTab").Content=L("Мои публикации","My uploads","Мої публікації");C<TextBlock>("PublicationsTitle").Text=L("Мои публикации","My uploads","Мої публікації");C<TextBlock>("PublicationsHint").Text=L("Здесь только твои паки. Удалённый пак исчезнет из общего каталога.","Only your packs appear here. Deleting removes a pack from the shared catalog.","Тут лише твої паки. Видалений пак зникне зі спільного каталогу.");C<Button>("RefreshPublicationsButton").Content=L("Обновить","Refresh","Оновити");C<Button>("AccountButton").Content=username==""?L("Войти","Sign in","Увійти"):"@"+username;
   C<Button>("ImportButton").Content=L("Импорт пака","Import pack","Імпорт пака");C<Button>("ExportButton").Content=L("Экспорт пака","Export pack","Експорт пака");C<TextBlock>("LibraryTitle").Text=L("Моя подборка","My collection","Моя добірка");C<TextBlock>("LibraryHint").Text=L("Сними галочку, чтобы оставить звук Discord. WAV или MP3, до 10 МБ на звук.","Uncheck an event to keep Discord's sound. WAV or MP3, up to 10 MB per sound.","Зніми позначку, щоб залишити звук Discord. WAV або MP3, до 10 МБ на звук.");C<TextBlock>("PackNameLabel").Text=L("Название твоего пака","Your pack name","Назва твого пака");
   C<Button>("ApplyButton").Content=L("Применить в Discord  →","Apply to Discord  →","Застосувати в Discord  →");C<TextBlock>("FooterTitle").Text=L("Твоя подборка","Your collection","Твоя добірка");C<Button>("RestoreButton").Content=L("Вернуть звуки Discord","Restore Discord sounds","Повернути звуки Discord");C<Button>("StatusButton").Content=L("Диагностика","Diagnostics","Діагностика");C<Button>("SaveServerButton").Content=L("Подключиться","Connect","Підключитися");C<TextBlock>("SettingsTitle").Text=L("Настройки воркшопа","Workshop settings","Налаштування воркшопу");C<TextBlock>("ServerLabel").Text=L("Адрес общего сервера","Shared server address","Адреса спільного сервера");C<TextBlock>("ServerHelp").Text=L("Общий воркшоп хранит аккаунты и паки в облаке Cloudflare. Для подключения нужен опубликованный бесплатный Worker.","The shared workshop stores accounts and packs in Cloudflare. Connect a deployed free Worker to enable it.","Спільний воркшоп зберігає акаунти та паки в Cloudflare. Для підключення потрібен опублікований безкоштовний Worker.");
