  Button B(string text,Action action,bool accent=false){var b=new Button {Content=text,Margin=new Thickness(4),Padding=new Thickness(14,8,14,8)};if(accent){b.Background=Orange;b.Foreground=Brushes.Black;b.BorderBrush=Orange;}b.Click+=(s,e)=>{try{action();}catch(Exception ex){Fail(ex);}};return b;}
  Button BA(string text,Func<Task> action,bool accent=false){var b=B(text,()=>{},accent);b.Click+=async(s,e)=>{if(busy)return;busy=true;b.IsEnabled=false;try{await action();}catch(Exception ex){Fail(ex);}finally{busy=false;b.IsEnabled=true;}};return b;}
  UIElement Wave(string seed,int index){var grid=new Grid {Height=112,ClipToBounds=true};Color a=index%3==0?Color.FromRgb(82,30,8):index%3==1?Color.FromRgb(41,26,70):Color.FromRgb(17,49,48);grid.Background=new LinearGradientBrush(a,Color.FromRgb(14,14,17),50);var bars=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};int n=0;foreach(char ch in seed)n+=ch;var random=new Random(n);for(int i=0;i<39;i++)bars.Children.Add(new Border {Width=3,Height=random.Next(8,70),CornerRadius=new CornerRadius(2),Margin=new Thickness(2,0,2,0),Background=new SolidColorBrush(index%3==0?Color.FromRgb(255,103,27):index%3==1?Color.FromRgb(169,130,236):Color.FromRgb(72,204,170)),Opacity=.5+random.NextDouble()*.5});grid.Children.Add(bars);return grid;}
  Border Card(string name,string author,string badge,int index,Func<Task> preview,Func<Task> use){var body=new StackPanel();var artwork=new Grid();artwork.Children.Add(Wave(name,index));var tag=new Border {Background=new SolidColorBrush(Color.FromArgb(180,0,0,0)),CornerRadius=new CornerRadius(10),Padding=new Thickness(8,4,8,4),HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top,Margin=new Thickness(12)};tag.Child=new TextBlock {Text=badge,FontSize=10,FontWeight=FontWeights.SemiBold};artwork.Children.Add(tag);body.Children.Add(artwork);var detail=new Grid {Margin=new Thickness(13,12,10,12)};detail.RowDefinitions.Add(new RowDefinition());detail.RowDefinitions.Add(new RowDefinition());var title=new TextBlock {Text=name,FontWeight=FontWeights.SemiBold,TextTrimming=TextTrimming.CharacterEllipsis,FontSize=15};detail.Children.Add(title);var by=new TextBlock {Text=author,Foreground=Muted,FontSize=11,Margin=new Thickness(0,7,0,42),TextTrimming=TextTrimming.CharacterEllipsis};Grid.SetRow(by,1);detail.Children.Add(by);var actions=new StackPanel {Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,30,0,0)};actions.Children.Add(BA("▶",preview));actions.Children.Add(BA(L("Выбрать","Use pack","Вибрати"),use,true));Grid.SetRow(actions,1);detail.Children.Add(actions);body.Children.Add(detail);return new Border {Child=body,Background=new SolidColorBrush(Color.FromRgb(18,18,21)),BorderBrush=new SolidColorBrush(Color.FromRgb(43,43,48)),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(16),ClipToBounds=true,Margin=new Thickness(6),MinWidth=270};}
  void DrawPresets(){var host=C<System.Windows.Controls.Primitives.UniformGrid>("PresetCards");host.Children.Clear();for(int i=0;i<presets.Count;i++){var pack=presets[i];host.Children.Add(Card(pack.Name,"SoundSpace · TeamSpeak 3",L("ПРЕСЕТ","PRESET","ПРЕСЕТ"),i,()=>{PreviewPack(pack);return Task.FromResult(0);},()=>{Use(pack,true);return Task.FromResult(0);}));}}
  void DrawCategories(){var host=C<WrapPanel>("CategoryChips");host.Children.Clear();string[] ids={"All","Classic","Gaming","Memes","Anime","Minimal","Music","Other"};string[] ru={"Все","Классика","Игры","Мемы","Аниме","Минимализм","Музыка","Другое"};string[] uk={"Усі","Класика","Ігри","Меми","Аніме","Мінімалізм","Музика","Інше"};for(int i=0;i<ids.Length;i++){string id=ids[i];var chip=BA(language=="RU"?ru[i]:language=="UK"?uk[i]:id,async()=>{category=id;DrawCategories();await Refresh(false);},category==id);chip.Padding=new Thickness(13,7,13,7);host.Children.Add(chip);}}
  void DrawSounds(){var rows=C<StackPanel>("SoundRows");rows.Children.Clear();foreach(var key in Packs.Keys){string id=key;bool previous=enabled.ContainsKey(key)?enabled[key].IsChecked==true:!String.IsNullOrEmpty(sounds[key]);var row=new Grid {Margin=new Thickness(0,0,0,9)};row.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(230)});row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition {Width=GridLength.Auto});row.ColumnDefinitions.Add(new ColumnDefinition {Width=GridLength.Auto});var check=new CheckBox {Content=Event(key),IsChecked=previous,VerticalAlignment=VerticalAlignment.Center};enabled[key]=check;check.Checked+=(s,e)=>Save();check.Unchecked+=(s,e)=>Save();row.Children.Add(check);var label=new TextBlock {Text=String.IsNullOrEmpty(sounds[key])?"Discord default":Path.GetFileName(sounds[key]),Foreground=Muted,VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(12,0,12,0)};filenames[key]=label;Grid.SetColumn(label,1);row.Children.Add(label);var choose=B(L("Выбрать файл","Choose file","Вибрати файл"),()=>Choose(id));Grid.SetColumn(choose,2);row.Children.Add(choose);var play=B("▶",()=>Play(sounds[id]));Grid.SetColumn(play,3);row.Children.Add(play);rows.Children.Add(new Border {Child=row,Padding=new Thickness(16,10,12,2),CornerRadius=new CornerRadius(14),Background=new SolidColorBrush(Color.FromRgb(20,20,24)),BorderBrush=new SolidColorBrush(Color.FromRgb(40,40,45)),BorderThickness=new Thickness(1),Margin=new Thickness(0,0,0,8)});}}
  void Use(Pack pack,bool show){foreach(var key in Packs.Keys){SoundSpec spec;sounds[key]=pack.Sounds.TryGetValue(key,out spec)?Path.Combine(pack.Root,"sounds",spec.File):null;if(enabled.ContainsKey(key))enabled[key].IsChecked=!String.IsNullOrEmpty(sounds[key]);}C<TextBox>("PackNameBox").Text=pack.Name;C<TextBlock>("CurrentPack").Text=pack.Name+"  ·  "+pack.Author;if(show){DrawSounds();View("Library");Save();Log(L("Пак выбран: ","Selected pack: ","Вибраний пак: ")+pack.Name);}}
  void Play(string file){if(String.IsNullOrEmpty(file))return;Packs.ValidateAudio(file);player.Close();player.Open(new Uri(file));player.Play();}
  void PreviewPack(Pack pack){string key=new[]{"deafen","unmute","mute"}.FirstOrDefault(k=>pack.Sounds.ContainsKey(k))??pack.Sounds.Keys.FirstOrDefault();if(key!=null)Play(Path.Combine(pack.Root,"sounds",pack.Sounds[key].File));}
  void Choose(string key){var dialog=new OpenFileDialog {Filter="Audio (*.wav;*.mp3)|*.wav;*.mp3"};if(dialog.ShowDialog(Window)!=true)return;Packs.ValidateAudio(dialog.FileName);string folder=Path.Combine(Packs.DataRoot,"custom",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string path=Path.Combine(folder,key+Path.GetExtension(dialog.FileName).ToLowerInvariant());File.Copy(dialog.FileName,path);sounds[key]=path;enabled[key].IsChecked=true;filenames[key].Text=Path.GetFileName(dialog.FileName);Save();}
  Dictionary<string,string> Selection(){var result=new Dictionary<string,string>();foreach(var key in Packs.Keys)if(enabled[key].IsChecked==true){if(String.IsNullOrEmpty(sounds[key]))throw new InvalidOperationException(Event(key)+": choose an audio file.");result[key]=sounds[key];}return result;}
  void Import(){var d=new OpenFileDialog {Filter="Sound packs (*.dspack)|*.dspack"};if(d.ShowDialog(Window)==true)Use(Packs.Import(d.FileName),true);}
  void Export(){var d=new SaveFileDialog {Filter="Sound packs (*.dspack)|*.dspack",FileName="my-sounds.dspack"};if(d.ShowDialog(Window)==true){Packs.Export(d.FileName,C<TextBox>("PackNameBox").Text,Selection());Log("Exported: "+d.FileName);}}
  async Task RunPatch(string mode){if(mode!="Status"&&Process.GetProcessesByName("Discord").Length>0)throw new InvalidOperationException(L("Сначала полностью закрой Discord через значок возле часов.","Fully quit Discord using its tray icon first.","Спочатку повністю закрий Discord через значок біля годинника."));string profile=mode=="Apply"?Packs.Stage(Selection()):null;C<Button>("ApplyButton").IsEnabled=false;try{player.Close();Log(mode+"…");var result=await Task.Run(()=>{var info=new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+Path.Combine(root,"Manage-Sounds.ps1")+"\" -Mode "+mode+(profile==null?"":" -PackPath \""+profile+"\"")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(info)){var output=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();p.WaitForExit();Task.WaitAll(output,error);return Tuple.Create(p.ExitCode,output.Result+error.Result);}});Log(result.Item2);if(result.Item1!=0)throw new InvalidOperationException(L("Не удалось применить. Подробности в разделе «Настройки».","Operation failed. See Settings for details.","Операцію не завершено. Подробиці в налаштуваннях."));}finally{C<Button>("ApplyButton").IsEnabled=true;}}
  void Offline(){C<WrapPanel>("CommunityCards").Children.Clear();C<TextBlock>("CommunityStatus").Text=L("Общий воркшоп ещё не подключён. Открой «Настройки», чтобы указать адрес бесплатного облачного сервера. Здесь будут настоящие паки пользователей — без выдуманных авторов.","The shared workshop is not connected yet. Add the free cloud endpoint in Settings. Real user packs will appear here; no invented creators or download counts.","Спільний воркшоп ще не підключено. Вкажи адресу безкоштовного хмарного сервера в налаштуваннях. Тут будуть справжні паки користувачів, без вигаданих авторів.");}
  WebClient Client(bool authenticated=false){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var c=new WebClient {Encoding=Encoding.UTF8};c.Headers["User-Agent"]="SoundSpace-Preview";if(authenticated&&token!="")c.Headers["Authorization"]="Bearer "+token;return c;}
  async Task<Dictionary<string,object>> Api(string route,object body=null,string method=null){
   if(server=="")throw new InvalidOperationException(L("Сначала подключи сервер в настройках.","Connect a server in Settings first.","Спочатку підключи сервер у налаштуваннях."));
   try{using(var c=Client(true)){string text;if(body==null&&method==null)text=await c.DownloadStringTaskAsync(server+route);else{c.Headers["Content-Type"]="application/json; charset=utf-8";text=await c.UploadStringTaskAsync(server+route,method??"POST",body==null?"":Packs.Json.Serialize(body));}return Packs.Json.Deserialize<Dictionary<string,object>>(text);}}
   catch(WebException error){throw new InvalidOperationException(AccountValidation.ReadError(error,language));}
  }
  async Task Refresh(bool more){if(server==""){Offline();return;}string query=C<TextBox>("SearchBox").Text.Trim();var result=await Api("/api/packs?q="+Uri.EscapeDataString(query)+"&category="+Uri.EscapeDataString(category)+"&sort="+sort+"&cursor="+(more?cursor:""));if(!more)C<WrapPanel>("CommunityCards").Children.Clear();int index=0;foreach(var value in (IEnumerable)result["packs"]){var item=Packs.Dict(value);string id=Packs.Text(item,"id");if(!Regex.IsMatch(id,"^[a-f0-9-]{36}$"))continue;string name=Packs.Text(item,"name"),author=Packs.Text(item,"author"),label=Packs.Text(item,"category");var card=Card(name,"@"+author+"  ·  "+Packs.Text(item,"downloads")+" ↓",label,index++,async()=>{PreviewPack(await Download(item));},async()=>{var pack=await Download(item);pack.Author=author;Use(pack,true);});card.Width=300;C<WrapPanel>("CommunityCards").Children.Add(card);}cursor=Packs.Text(result,"nextCursor");C<Button>("LoadMoreButton").Visibility=cursor==""?Visibility.Collapsed:Visibility.Visible;C<TextBlock>("CommunityStatus").Text=C<WrapPanel>("CommunityCards").Children.Count==0?L("Паков пока нет. Опубликуй первый!","No packs yet. Share the first one!","Паків ще немає. Опублікуй перший!"):L("Настоящие паки пользователей","Packs shared by real users","Справжні паки користувачів");}
  async Task<Pack> Download(Dictionary<string,object> item){string id=Packs.Text(item,"id"),hash=Packs.Text(item,"sha256");if(!Regex.IsMatch(id,"^[a-f0-9-]{36}$")||!Regex.IsMatch(hash,"^[a-f0-9]{64}$"))throw new InvalidDataException("Invalid pack metadata");string dir=Path.Combine(Packs.DataRoot,"downloads");Directory.CreateDirectory(dir);string file=Path.Combine(dir,hash+".dspack");if(!File.Exists(file)){using(var c=Client()){c.DownloadProgressChanged+=(s,e)=>{if(e.BytesReceived>75L*1024*1024)c.CancelAsync();};await c.DownloadFileTaskAsync(server+"/api/packs/"+id+"/download",file);}}if(Packs.Hash(file)!=hash)throw new InvalidDataException("SHA256 mismatch");return Packs.Import(file);}
  Window Dialog(string title,out StackPanel panel){var d=new Window {Owner=Window,Title=title,Width=440,Height=430,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=new SolidColorBrush(Color.FromRgb(17,17,20)),Foreground=Brushes.White,FontFamily=new FontFamily("Segoe UI"),FontSize=14};d.Resources=Window.Resources;panel=new StackPanel {Margin=new Thickness(28)};d.Content=panel;panel.Children.Add(new TextBlock {Text=title,FontSize=23,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,20)});return d;}
  async Task Publish(){if(server==""){View("Settings");Offline();return;}if(token==""){await Account();if(token=="")return;}var selection=Selection();if(selection.Count==0)throw new InvalidOperationException("Select at least one sound.");StackPanel panel;var d=Dialog(L("Поделиться паком","Share a pack","Поділитися паком"),out panel);var name=new TextBox {Text=C<TextBox>("PackNameBox").Text,Margin=new Thickness(0,0,0,12)};var description=new TextBox {Text="",Height=80,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,12)};var group=new ComboBox {ItemsSource=new[]{"Classic","Gaming","Memes","Anime","Minimal","Music","Other"},SelectedIndex=0,Margin=new Thickness(0,0,0,14)};panel.Children.Add(name);panel.Children.Add(description);panel.Children.Add(group);var message=new TextBlock {Foreground=Orange,TextWrapping=TextWrapping.Wrap};var send=BA(L("Опубликовать для всех","Publish to everyone","Опублікувати для всіх"),async()=>{try{string folder=Path.Combine(Packs.DataRoot,"exports");Directory.CreateDirectory(folder);string file=Path.Combine(folder,Guid.NewGuid().ToString("N")+".dspack");Packs.Export(file,name.Text,selection);using(var c=Client(true)){c.Headers["Content-Type"]="application/octet-stream";byte[] bytes=File.ReadAllBytes(file);if(bytes.Length>8*1024*1024)throw new InvalidDataException("Cloud pack limit: 8 MB.");await c.UploadDataTaskAsync(server+"/api/packs?name="+Uri.EscapeDataString(name.Text)+"&description="+Uri.EscapeDataString(description.Text)+"&category="+group.SelectedItem,"POST",bytes);}d.Close();View("Discover");await Refresh(false);}catch(Exception ex){message.Text=ex.Message;}},true);panel.Children.Add(send);panel.Children.Add(message);d.ShowDialog();}
  void Save(){if(loading)return;try{Directory.CreateDirectory(Packs.DataRoot);string protectedToken=token==""?"":Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(token),null,DataProtectionScope.CurrentUser));var checks=enabled.ToDictionary(x=>x.Key,x=>x.Value.IsChecked==true);var settings=new {language=language,name=C<TextBox>("PackNameBox").Text,files=sounds,enabled=checks,server=server,username=username,token=protectedToken};File.WriteAllText(Path.Combine(Packs.DataRoot,"modern-settings.json"),Packs.Json.Serialize(settings),new UTF8Encoding(false));}catch(Exception e){Log(e.Message);}}
  void Load(){string file=Path.Combine(Packs.DataRoot,"modern-settings.json");if(!File.Exists(file))return;try{var d=Packs.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file,Encoding.UTF8));language=Packs.Text(d,"language");if(!new[]{"RU","EN","UK"}.Contains(language))language="RU";server=Packs.Text(d,"server");Uri uri;if(server!=""&&(!Uri.TryCreate(server,UriKind.Absolute,out uri)||(uri.Scheme!="https"&&!(uri.Scheme=="http"&&uri.IsLoopback))))server="";C<TextBox>("ServerBox").Text=server;username=Packs.Text(d,"username");string encrypted=Packs.Text(d,"token");if(encrypted!="")try{token=Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(encrypted),null,DataProtectionScope.CurrentUser));}catch{username="";}var files=Packs.Dict(d["files"]);foreach(var key in Packs.Keys){string path=Packs.Text(files,key);if(File.Exists(path))sounds[key]=path;}DrawSounds();var flags=Packs.Dict(d["enabled"]);foreach(var key in Packs.Keys)enabled[key].IsChecked=flags.ContainsKey(key)&&Convert.ToBoolean(flags[key]);C<TextBox>("PackNameBox").Text=Packs.Text(d,"name");}catch(Exception e){Log(e.Message);}}
 }
